unsafe extern "C":
    # void sort_scores(int32_t* base, size_t n, int (*cmp)(const int32_t*, const int32_t*));
    @ffi(param(base, borrowed, count(n), exclusive), param(cmp, callback(borrowed)))
    safe fn sort_scores(ref mut base: MutSpan[i32], n: usize, cmp: extern "C" fn(*i32, *i32) -> c_int)

fn by_score(a: *i32, b: *i32) -> c_int:
    # SAFETY: `sort_scores` passes two elements of the span it sorts
    unsafe:
        if a.read() < b.read():
            return -1
        if a.read() > b.read():
            return 1
    return 0

