    base: *u8
    len: usize

# SAFETY(ffi): the declaration below matches the C library's writev
unsafe extern "C":
    @safety("each of the `iovcnt` elements at `iov` has `base` pointing at `len` readable bytes")
    @ffi(no_callbacks)
    unsafe fn writev(fd: c_int, iov: *IoVec, iovcnt: c_int) -> isize

