from std.sync import Sender, channel

struct Request:
    path: String

fn handle(req: Request) -> Result[String]:
    if req.path.is_empty():
        return Err(AnyError.msg(owns f"empty request path"))
    return Ok(copy of req.path)

fn serve(tx: Sender[Result[String]]):
    for p in ["/index", ""]:
        tx.send(owns handle(Request(path=String(p)))).expect("receiver is gone")

fn main():
    tx, rx = channel[Result[String]](capacity=8)
    worker = thread.spawn(owns fn() owns tx: serve(tx))
    for r in rx:
        match r:
            Ok(body):
                println(body)
            Err(e):
                println(f"error: {e}")
    worker.join()

import std.thread
from std.sync import RwLock

class Texture:
    width: int = 0
    height: int = 0

fn decode(name: StrView) -> Result[Texture]:
    if name.ends_with(".png"):
        return Ok(Texture(width=64, height=64))
    return Err(AnyError.msg(owns f"not a png: {name}"))

class Assets:
    loaded: RwLock[Array[Result[Texture]]] = RwLock([])

fn load_into(assets: thread_shared Assets, name: StrView):
    r = decode(name)
    with g = assets.loaded.write():
        g.push(owns r)

fn main():
    assets = thread_shared Assets()
    h = thread.spawn(owns fn() thread_shared assets: load_into(assets, "hero.png"))
    h.join()
    with g = assets.loaded.read():
        println(g.len())

pub interface Source:
