import std.thread
from std.sync import Receiver, Sender, channel

@derive(Error)
enum RequestError:
    @error("bad header {name}")
    BadHeader(name: String)

fn handle(line: StrView) -> Result[int, RequestError]:
    if line.find(":").is_none():
        return Err(RequestError.BadHeader(name=String(line)))
    return Ok(line.len())

fn logger(rx: Receiver[AnyError]) -> int:
    n = 0
    for e in rx:
        eprintln(f"logged: {e}")
        n += 1
    return n

fn serve(owns tx: Sender[AnyError]):
    for line in ["Host: a", "garbage"]:
        match handle(line):
            Ok(n):
                println(n)
            Err(e):
                tx.send(owns AnyError.from(owns e)).expect("logger is gone")

fn main():
    tx, rx = channel[AnyError](capacity=16)
    log = thread.spawn(owns fn() owns rx: logger(rx))
    serve(owns tx)
    println(log.join())

@noalloc
