class Inventory:
    gold: int = 0

## a shop's error: the buyer's inventory, handed back so the caller can show it
@derive(Error)
enum TradeError:
    @error("not enough gold")
    Short(inventory: shares mut Inventory)

fn buy(inv: shares mut Inventory, price: int) -> Result[int, TradeError]:
    if inv.gold < price:
        return Err(TradeError.Short(inventory=shares mut inv))
    return Ok(inv.gold - price)

fn main() -> Result[void]:
    inv = shares mut Inventory(gold=5)
    println(buy(inv, 10)?)
    return Ok(())

import std.thread

fn parse_port(text: StrView) -> Result[int]:
    n = text.trim().parse[int]()?
    return Ok(n)

fn count_ok(rs: Span[Result[int]]) -> int:
    n = 0
    for r in rs:
        if r.is_ok():
            n += 1
    return n

fn count_failed(rs: Span[Result[int]]) -> int:
    n = 0
    for r in rs:
        if r.is_err():
            n += 1
    return n

fn main():
    results: Array[Result[int]] = []
    for s in ["8080", "http", "443"]:
        results.push(owns parse_port(s))
    with scope = thread.scope():
        a = scope.spawn(owns fn() => count_ok(results))
        b = scope.spawn(owns fn() => count_failed(results))
        println(a.join(), b.join())

